          event.key === 'ArrowRight' ||
          event.key === 'ArrowUp' ||
          event.key === 'ArrowDown'
        ) {
          event.preventDefault();
          moveFocus(index, event.key, size);
        }
      }}
      onClick={(event) => {
        activate(index);
        clicked(event.currentTarget);
      }}
